INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (106, 1, '<newsletter-caption-review@comms.example>', 'Caption review for the June volunteering newsletter', 'comms@example.com', '["ella.ops@example.com"]', '[]', '[]', '2026-06-26T09:35:00+08:00', 'The newsletter editor removed two employee surnames from the photo captions and replaced a participant quote with the approved aggregate volunteering theme. The signed release remains with the campaign file.', NULL, 1, 0, 0, NULL, NULL, '{"X-Campaign":"VOL-JUN"}', 106, 214, '2026-06-26T01:35:00Z');
