INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (212, 1, '<spring-salon-retro@learning.example>', 'Spring reading salon retrospective and attendance gap', 'learning-programs@example.com', '["ella.ops@example.com"]', '["people-ops@example.com"]', '[]', '2026-05-12T10:18:00+08:00', 'The April salon closed with 46 attendees against 58 registrations. Six books were left over, two table groups had only one department represented, and the facilitator asked us to mix functions before publishing the next seating plan.', NULL, 1, 0, 0, NULL, NULL, '{"X-Program":"learning-salon"}', 212, 227, '2026-05-12T02:19:31Z');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (227, 1, '<ledger-correction-may@finance.example>', 'Correction to April salon cost center', 'ap-helpdesk@example.com', '["ella.ops@example.com"]', '[]', '[]', '2026-05-19T15:42:00+08:00', 'Invoice AP-48317 was coded to employee meals, but the approved purchase order split CNY 3,680 for books to Learning and CNY 1,240 for refreshments to Team Operations. Please keep the revised allocation with the event closeout.', NULL, 1, 1, 0, NULL, NULL, '{"X-Ticket":"FIN-7318"}', 227, 241, '2026-05-19T07:45:12Z');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (241, 1, '<guest-window-june@maya-office.example>', 'June guest window moved after travel change', 'coordinator@maya-office.example', '["ella.ops@example.com"]', '[]', '[]', '2026-05-27T11:06:00+08:00', 'Maya could not keep the June 9 lunch slot after her rail itinerary changed. The replacement window was June 16 from 16:00 to 17:00, with a 20-minute sound check and no recording of the audience discussion.', NULL, 1, 0, 0, NULL, NULL, '{"X-Thread":"guest-window-june"}', 241, 213, '2026-05-27T03:08:44Z');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (266, 1, '<capacity-revision-riverside@venue.example>', 'Riverside Room capacity reduced for stage layout', 'events@riversidehouse.example', '["ella.ops@example.com"]', '[]', '[]', '2026-06-03T09:34:00+08:00', 'Once the low stage and two wheelchair turning areas are installed, Riverside Room supports 64 seated guests rather than the brochure limit of 82. A theatre layout would remove discussion tables and is not suitable for the salon format.', NULL, 1, 1, 0, NULL, NULL, '{"X-Quote":"RH-260603"}', 266, 225, '2026-06-03T01:36:09Z');
