INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (347, 1, '<hearing-loop-loan@workplace.example>', 'Portable hearing loop available for internal events', 'accessibility@workplace.example', '["ella.ops@example.com"]', '[]', '[]', '2026-06-24T10:07:00+08:00', 'The workplace team can loan the portable hearing loop and two table microphones at no charge. Requests need three business days, a named equipment custodian, and a 30-minute test before guests arrive.', NULL, 1, 0, 0, NULL, NULL, '{"X-Asset":"ACCESS-KIT-04"}', 347, 198, '2026-06-24T02:10:03Z');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (381, 1, '<allergen-separation-audit@people.example>', 'Peanut-free service audit from the design offsite', 'wellbeing@example.com', '["ella.ops@example.com"]', '[]', '[]', '2026-07-02T14:16:00+08:00', 'At the design offsite, peanut-free meals shared one unlabeled serving tong with desserts. No exposure was reported, but the closeout requires sealed individual portions, a separate pickup point, and one catering contact accountable for labels.', NULL, 1, 1, 0, NULL, NULL, '{"X-Incident":"WB-260628"}', 381, 237, '2026-07-02T06:18:39Z');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (419, 1, '<teaser-permission-denied@comms.example>', 'Do not reuse author portrait from winter campaign', 'brand-rights@example.com', '["ella.ops@example.com"]', '["comms@example.com"]', '[]', '2026-07-07T09:26:00+08:00', 'The winter campaign license covered the intranet banner through March only. It does not authorize a new event teaser, social post, or printed poster, so use a licensed book-cover asset or wait for fresh written permission.', NULL, 1, 1, 0, NULL, NULL, '{"X-Rights":"BR-8826"}', 419, 211, '2026-07-07T01:29:25Z');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (458, 1, '<feedback-export-removal@privacy.example>', 'Remove names from the February feedback export', 'privacy-office@example.com', '["ella.ops@example.com"]', '[]', '[]', '2026-07-10T17:08:00+08:00', 'The February spreadsheet included employee names beside comments about managers. Replace it in the archive with response codes, preserve the access log, and circulate only the aggregate themes approved by People Operations.', NULL, 1, 1, 0, NULL, NULL, '{"X-Case":"PRIV-2064"}', 458, 207, '2026-07-10T09:11:02Z');
