INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (557, 1, '<coupon-expiry-business@eastbridgebooks.example>', 'Business account voucher expired before checkout', 'account-team@eastbridgebooks.example', '["ella.ops@example.com"]', '[]', '[]', '2026-07-18T10:32:00+08:00', 'Voucher READ-MAY-300 applied only to orders confirmed by June 30 and cannot be reactivated. The account still receives the published 8 percent case discount when a single title reaches 40 copies.', NULL, 1, 0, 0, NULL, NULL, '{"X-Account":"EB-CORP-118"}', 557, 185, '2026-07-18T02:35:41Z');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (612, 1, '<mixed-table-lessons@learning.example>', 'Table mix lessons from the product and support exchange', 'nora.liu@example.com', '["ella.ops@example.com"]', '[]', '[]', '2026-07-22T16:37:00+08:00', 'Groups of six worked when each table had at least three functions and no manager sat with all direct reports. The two groups built from alphabetical order stalled, so the facilitator recommends publishing table numbers without employee attributes.', NULL, 0, 0, 1, NULL, NULL, '{"X-Program":"function-exchange"}', 612, 221, '2026-07-22T08:39:47Z');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (674, 1, '<sound-check-findings@facilities.example>', 'Cloud Loft sound test showed corridor bleed', 'av-support@example.com', '["ella.ops@example.com"]', '[]', '[]', '2026-07-24T11:13:00+08:00', 'During the July test, speech at the rear tables was clear with both portable microphones, but corridor announcements entered the room whenever the east door opened. Facilities recommends using the west entrance during moderated discussion.', NULL, 0, 0, 0, NULL, NULL, '{"X-Test":"AV-CL-0724"}', 674, 218, '2026-07-24T03:15:36Z');
