INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (811, 1, '<internal-summary-summer@people.example>', 'Internal summary of summer learning circles', 'people-analytics@example.com', '["ella.ops@example.com"]', '[]', '[]', '2026-07-29T15:21:00+08:00', 'Across three summer circles, attendance averaged 81 percent and mixed-function tables generated more follow-up introductions. The approved summary omits free-text comments, dietary requests, accessibility needs, and guest contact details.', NULL, 0, 0, 0, NULL, NULL, '{"X-Report":"PA-LC-Q2"}', 811, 210, '2026-07-29T07:23:55Z');
